### 2.1 Patch A — `packages/opencode/src/provider/provider.ts` (v1)

**Hunk A1 — insert `wrapBodyIdle` after `wrapSSE` (after L82, before `function timeoutController`):**

```ts
// NEW: idle-progress deadline for non-SSE response bodies (Option A').
// The timer resets on every chunk, so a slow-but-progressing body is never
// aborted (hy3 F2 preserved); only a body that stalls >= ms between chunks is.
// Optional absoluteMs is a belt-and-braces total cap (opt-in, default off).
function wrapBodyIdle(res: Response, ms: number, ctl: AbortController, absoluteMs?: number) {
  if (typeof ms !== "number" || ms <= 0) return res
  if (!res.body) return res
  const reader = res.body.getReader()
  let settled = false
  let streamCtl: ReadableStreamDefaultController<Uint8Array> | undefined
  let idleId: ReturnType<typeof setTimeout> | undefined
  let absoluteId: ReturnType<typeof setTimeout> | undefined

  // Shared failure path for the idle timer, the absolute-cap timer, and
  // consumer cancel. Deterministically terminates the stream: errors the
  // stream controller (so the consumer's read settles even if pull never
  // ran), aborts the request controller, and clears BOTH timers.
  const fail = (err: Error) => {
    if (settled) return
    settled = true
    if (idleId) clearTimeout(idleId)
    if (absoluteId) clearTimeout(absoluteId)
    ctl.abort(err)
    streamCtl?.error(err)
    void reader.cancel(err).catch(() => {})
  }

  const body = new ReadableStream<Uint8Array>({
    start(ctrl) {
      // ReadableStream calls start synchronously at construction, so the
      // absolute-cap timer (armed below) always has a controller to error.
      streamCtl = ctrl
    },
    async pull(ctrl) {
      if (settled) return
      const part = await new Promise<Awaited<ReturnType<typeof reader.read>>>((resolve, reject) => {
        idleId = setTimeout(() => {
          const err = new ProviderError.ResponseStreamError("Body read timed out")
          fail(err)
          reject(err)
        }, ms)
        reader.read().then(
          (part) => {
            if (idleId) clearTimeout(idleId)
            idleId = undefined
            resolve(part)
          },
          (err) => {
            if (idleId) clearTimeout(idleId)
            idleId = undefined
            reject(err)
          },
        )
      })
      if (settled) return
      if (part.done) {
        settled = true
        if (absoluteId) clearTimeout(absoluteId)
        ctrl.close()
        return
      }
      ctrl.enqueue(part.value)
    },
    async cancel(reason) {
      fail(reason instanceof Error ? reason : new Error(String(reason)))
    },
  })

  if (typeof absoluteMs === "number" && absoluteMs > 0) {
    absoluteId = setTimeout(() => {
      fail(new ProviderError.ResponseStreamError("Body read deadline exceeded"))
    }, absoluteMs)
  }

  const headers = new Headers(res.headers)
  // fetch() has already decoded content-encoding into res.body and the
  // re-chunked body no longer matches the original content-length. Keeping
  // these headers makes consumers re-decode (double-decode -> ZlibError in
  // the unbounded class) or wait on a stale length. Strip both.
  headers.delete("content-length")
  headers.delete("content-encoding")
  return new Response(body, {
    headers,
    status: res.status,
    statusText: res.statusText,
  })
}
```

**Lifecycle guarantees (closes F7/V3):** (1) the absolute-cap callback calls `fail`, which has the stream controller (captured in `start`) and calls `streamCtl?.error(err)` — the consumer's read settles deterministically even when the timer fires before the first `pull`; (2) the idle callback clears `absoluteId` via `fail` (no 55-min timer leak); (3) `cancel()` clears both timers via `fail` before any early-return; (4) `settled` prevents `ctrl.close()` after `ctrl.error()`; (5) `reader.cancel(...).catch(() => {})`; (6) `pull` early-returns once settled.

